#!/usr/bin/env python3
import csv, io, json, os, re, sys
from datetime import datetime, timedelta, timezone


def read_exports(d):
    rows = []
    ed = os.path.join(d, "exports")
    for name in sorted(os.listdir(ed)):
        p = os.path.join(ed, name)
        if not name.endswith(".csv") or not os.path.isfile(p):
            continue
        with open(p, "rb") as f:
            text = f.read().decode("utf-8")
        if text.startswith("\ufeff"):
            text = text[1:]
        first = re.split(r"\r\n|\n|\r", text, 1)[0]
        delim = next((c for c in (",", ";", "\t") if c in first), ",")
        rd = csv.reader(io.StringIO(text, newline=""), delimiter=delim)
        header = None
        for cells in rd:
            if header is None:
                header = [c.strip() for c in cells]
                continue
            cells = [c.strip() for c in cells]
            if not any(cells):
                continue
            r = {}
            for i, h in enumerate(header):
                v = cells[i] if i < len(cells) else ""
                r[h] = v if v != "" else None
            rows.append(r)
    return rows


def parse_time(s, fmt, off):
    m = re.match(r"^(\d+)-(\d+)-(\d+)[T ](\d+):(\d+):(\d+)(?:\.(\d+))?\s*(Z|[+-]\d\d:?\d\d)?$", s.strip())
    y, mo, dd, h, mi, se = (int(m.group(i)) for i in range(1, 7))
    us = int((m.group(7) or "0").ljust(6, "0")[:6])
    tz = m.group(8)
    if fmt == "local" or tz is None:
        tz = off or "Z"
    if tz == "Z":
        o = 0
    else:
        sign = -1 if tz[0] == "-" else 1
        t = tz[1:].replace(":", "")
        o = sign * (int(t[:2]) * 60 + int(t[2:]))
    dt = datetime(y, mo, dd, h, mi, se, us)
    return dt - timedelta(minutes=o)


def parse_dur(s, fmt):
    s = s.strip()
    if fmt == "clock":
        t = 0
        for p in s.split(":"):
            t = t * 60 + int(p)
        return t
    return int(float(s))


def to_int(v):
    return int(str(v).strip())


def main(inp, outp):
    cb = json.load(open(os.path.join(inp, "codebook.json"), encoding="utf-8"))
    wj = json.load(open(os.path.join(inp, "weighting.json"), encoding="utf-8"))
    plan = json.load(open(os.path.join(inp, "tables.json"), encoding="utf-8"))
    versions = cb["versions"]
    vkeys = list(versions)
    Q = {q["id"]: q for q in cb["questions"]}
    raw = read_exports(inp)

    recs = []
    for r in raw:
        vk = str(r["form_version"])
        meta = versions[vk]["meta"]
        sub = r.get(meta["submitted"])
        rec = {
            "row": r, "v": vk,
            "id": r.get(meta["id"]),
            "complete": r.get(meta["status"]) == meta["complete"],
            "t": parse_time(sub, meta["submitted_format"], meta.get("utc_offset")) if sub else datetime.min,
            "dur": parse_dur(r[meta["duration"]], meta["duration_format"]) if r.get(meta["duration"]) else 0,
            "lp": int(r[meta["last_page"]]) if r.get(meta["last_page"]) else 0,
        }
        recs.append(rec)
    stats = {v: dict(rows=0, duplicates=0, short_partials=0, speeders=0, complete=0, partial=0) for v in vkeys}
    for rec in recs:
        stats[rec["v"]]["rows"] += 1

    best = {}
    for rec in recs:
        b = best.get(rec["id"])
        if b is None or (rec["complete"], rec["t"]) > (b["complete"], b["t"]):
            best[rec["id"]] = rec
    kept = []
    for rec in recs:
        if best[rec["id"]] is rec:
            kept.append(rec)
        else:
            stats[rec["v"]]["duplicates"] += 1
    k2 = []
    for rec in kept:
        if not rec["complete"] and rec["lp"] < cb["partial_min_page"]:
            stats[rec["v"]]["short_partials"] += 1
        else:
            k2.append(rec)
    med2 = {}
    for v in vkeys:
        ds = sorted(r["dur"] for r in k2 if r["v"] == v and r["complete"])
        n = len(ds)
        if n:
            med2[v] = ds[n // 2] * 2 if n % 2 else ds[n // 2 - 1] + ds[n // 2]
    k3 = []
    for rec in k2:
        if rec["complete"] and rec["dur"] * 5 < med2[rec["v"]]:
            stats[rec["v"]]["speeders"] += 1
        else:
            k3.append(rec)
    kept = k3
    for rec in kept:
        stats[rec["v"]]["complete" if rec["complete"] else "partial"] += 1

    # answers
    def read_answer(q, ent, row):
        t = q["type"]
        rc = ent.get("recode")

        def conv(x):
            if rc is not None:
                x = rc[x]
            return to_int(x)
        if t == "multi":
            chosen = set()
            if "columns" in ent:
                for code, col in ent["columns"].items():
                    if row.get(col) == "1":
                        chosen.add(to_int(code))
            else:
                cell = row.get(ent["column"])
                if cell:
                    for e in cell.split(ent["separator"]):
                        e = e.strip()
                        if e:
                            chosen.add(conv(e))
            if not chosen:
                return None
            opts = {o["code"]: o for o in q["options"]}
            excl = {c for c in chosen if opts[c].get("exclusive")}
            if excl and chosen - excl:
                chosen -= excl
            elif len(excl) >= 2:
                return None
            chosen = {c for c in chosen if not opts[c].get("missing")}
            return chosen or None
        cell = row.get(ent["column"])
        if cell is None:
            return None
        if t == "single":
            c = conv(cell)
            opts = {o["code"]: o for o in q["options"]}
            if opts[c].get("missing"):
                return None
            return c
        src = ent.get("source")
        if src == "band":
            return conv(cell)
        age = to_int(cell)
        if src == "birth_year":
            age = int(cb["reference_date"][:4]) - age
        for b in q["bands"]:
            if b["min"] <= age <= b["max"]:
                return b["code"]
        return None

    for rec in kept:
        ans = {}
        asked = {}

        def get(qid):
            if qid in asked:
                return asked[qid]
            q = Q[qid]
            ent = q["versions"].get(rec["v"])
            ok = ent is not None
            if ok and not rec["complete"] and ent["page"] > rec["lp"]:
                ok = False
            if ok and q.get("ask_if"):
                a = q["ask_if"]
                get(a["question"])
                av = ans.get(a["question"])
                if av is None:
                    ok = False
                else:
                    s = av if isinstance(av, set) else {av}
                    ok = bool(s & {to_int(c) for c in a["codes"]})
            asked[qid] = ok
            if ok:
                ans[qid] = read_answer(q, ent, rec["row"])
            return ok
        for qid in Q:
            get(qid)
        rec["ans"] = {k: v for k, v in ans.items() if v is not None}

    N = len(kept)
    w = [1.0] * N
    dims = []
    for d in wj["dimensions"]:
        qid = d["question"]
        present = {r["ans"][qid] for r in kept if qid in r["ans"]}
        tg = {to_int(k): float(v) for k, v in d["targets"].items()}
        tg = {k: v for k, v in tg.items() if k in present}
        s = sum(tg.values())
        if not tg or s <= 0:
            continue
        cats = {}
        for i, r in enumerate(kept):
            c = r["ans"].get(qid)
            if c in tg:
                cats.setdefault(c, []).append(i)
        dims.append(({c: v / s for c, v in tg.items()}, cats))
    for _ in range(wj["max_iterations"]):
        done = True
        for shares, cats in dims:
            T = sum(w[i] for idx in cats.values() for i in idx)
            fs = {}
            for c, idx in cats.items():
                W = sum(w[i] for i in idx)
                fs[c] = shares[c] * T / W if W else 1.0
            for c, idx in cats.items():
                for i in idx:
                    w[i] *= fs[c]
            if any(abs(f - 1) > wj["tolerance"] for f in fs.values()):
                done = False
        if done:
            break
    if N:
        m = sum(w) / N
        hi, lo = wj["cap"] * m, wj["floor"] * m
        w = [min(max(x, lo), hi) for x in w]
        sc = N / sum(w)
        w = [x * sc for x in w]

    summary = {"versions": [dict(version=v, **stats[v]) for v in vkeys], "respondents": N}
    if N:
        summary["effective_n"] = round(sum(w) ** 2 / sum(x * x for x in w), 2)
        summary["weight_min"] = round(min(w), 2)
        summary["weight_max"] = round(max(w), 2)
    else:
        summary["effective_n"] = summary["weight_min"] = summary["weight_max"] = None

    def codes_of(q):
        if q["type"] == "age":
            return [b["code"] for b in q["bands"]]
        return [o["code"] for o in q["options"] if not o.get("missing")]

    cols = [("total", None, None)]
    for bq in plan["banner"]:
        for c in codes_of(Q[bq]):
            cols.append((f"{bq}:{c}", bq, c))

    tables = []
    for t in plan["tables"]:
        qid = t["question"]
        q = Q[qid]
        multi = q["type"] == "multi"
        scores = {o["code"]: o.get("score") for o in q.get("options", [])}
        base_idx = [i for i, r in enumerate(kept) if qid in r["ans"]]
        outcols = []
        for cid, bq, bc in cols:
            idx = [i for i in base_idx if bq is None or kept[i]["ans"].get(bq) == bc]
            wb = sum(w[i] for i in idx)
            vals = {}
            keys = [(str(c), {c}) for c in codes_of(q)]
            keys += [(n["id"], {to_int(c) for c in n["codes"]}) for n in t.get("nets", [])]

            def has(i, cs):
                a = kept[i]["ans"][qid]
                return bool((a if multi else {a}) & cs)
            for k, cs in keys:
                vals[k] = round(100 * sum(w[i] for i in idx if has(i, cs)) / wb, 2) if idx and wb else None
            if t.get("mean"):
                vals["mean"] = round(sum(w[i] * scores[kept[i]["ans"][qid]] for i in idx) / wb, 2) if idx and wb else None
            outcols.append({"column": cid, "base": len(idx), "weighted_base": round(wb, 2) if idx else 0, "values": vals})
        tables.append({"table": t["id"], "columns": outcols})

    with open(outp, "w", encoding="utf-8") as f:
        json.dump({"survey": cb["survey"], "summary": summary, "tables": tables}, f, indent=1)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
